{"query":"query ReadProductMediaPage($productId: ID!, $after: String) {
  product(id: $productId) {
    id
    media(first: 2, after: $after) {
      nodes {
        id
        mediaContentType
        status
        mediaErrors { code message }
        ... on MediaImage { image { url altText } }
      }
      pageInfo { hasNextPage endCursor }
    }
  }
}"}
